const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const d = items[i].json;
  const w = Number(d.workouts||0);
  const facts = [];
  if (d.name) facts.push('Имя клиента: ' + d.name);
  facts.push('Тренировок за неделю: ' + w);
  if (Number(d.str_vol||0) > 0) { let s = 'Силовой объём: ' + d.str_vol + ' кг'; if (Number(d.str_vol_prev||0) > 0) s += ' (прошлая неделя ' + d.str_vol_prev + ' кг)'; facts.push(s); }
  if (Number(d.cardio_km||0) > 0) facts.push('Кардио: ' + d.cardio_km + ' км');
  if (Number(d.food_days||0) > 0) { let s = 'Дней с дневником питания: ' + d.food_days; if (d.kcal_day != null) s += ', в среднем ' + d.kcal_day + ' ккал/день'; if (d.prot_day != null) s += ', белок ' + d.prot_day + ' г/день'; facts.push(s); }
  if (d.weight_now != null) { let s = 'Текущий вес: ' + d.weight_now + ' кг'; if (d.weight_prev != null) s += ' (неделю назад ' + d.weight_prev + ' кг)'; facts.push(s); }
  const lang = String(d.language || 'Russian');
  const system = 'Ты — заботливый персональный фитнес-тренер. Напиши клиенту короткую тёплую НЕДЕЛЬНУЮ СВОДКУ его прогресса. ПИШИ СТРОГО НА ЯЗЫКЕ: ' + lang + ' (весь текст на этом языке). Используй ТОЛЬКО факты из списка ниже — не выдумывай и не добавляй чисел, которых нет. Тон поддерживающий; хвали за ПОСТОЯНСТВО и усилия, НЕ дави на снижение веса (вес упоминай нейтрально, как факт, без оценок «молодец что похудел»). 3-6 строк, можно эмодзи. Не пиши вступлений вроде «вот твоя сводка» — сразу обращайся к клиенту по делу. В конце мягко пригласи написать, если нужна корректировка.';
  const user = 'Факты за неделю:\n' + facts.join('\n');
  const payload = { model: 'claude-haiku-4-5-20251001', max_tokens: 500, system: system, messages: [{ role: 'user', content: user }] };
  out.push({ json: { bot_id: d.bot_id, user_id: d.user_id, chat_id: d.chat_id, bot_token: d.bot_token, payload: payload }, pairedItem: { item: i } });
}
return out;

const inp = $input.all();
const prompts = $('Промпт').all();
const out = [];
for (let i = 0; i < inp.length; i++) {
  const r = inp[i].json; const p = prompts[i].json;
  let text = '';
  try { text = r.content[0].text; } catch (e) { text = ''; }
  text = String(text || '').trim();
  if (!text) continue;
  out.push({ json: { bot_id: p.bot_id, user_id: p.user_id, chat_id: p.chat_id, bot_token: p.bot_token, text: text }, pairedItem: { item: i } });
}
return out;
